<script>
  import { onMount } from 'svelte';
  import { Activity, ArrowDownRight, ArrowUpRight, BarChart3, CirclePause, Globe2, Layers, RefreshCw, ShieldCheck, SlidersHorizontal } from '@lucide/svelte';
  export let underlying, underlyingName, expiry, selectedKey, contracts = [], expiries = [];
  export let chooseUnderlying, changeExpiry, selectLeg;
  let data = null, error = '', loading = false, identity = '', controller, revision = 0, lastFetch = 0, clock = Date.now();
  const fmt = (v, digits = 2) => v == null || !Number.isFinite(v) ? '—' : new Intl.NumberFormat('en-IN', { maximumFractionDigits: digits, minimumFractionDigits: digits }).format(v);
  const compact = v => v == null ? '—' : new Intl.NumberFormat('en-IN', { notation: 'compact', maximumFractionDigits: 2 }).format(v);
  const when = value => !value || String(value).startsWith('0001') ? '—' : new Date(typeof value === 'number' ? value * 1000 : value).toLocaleTimeString('en-GB', { timeZone: 'Asia/Kolkata', hour: '2-digit', minute: '2-digit', second: '2-digit' });
  $: currentContract = contracts.find(c => c.instrument_key === selectedKey);
  $: choices = contracts.filter(c => c.expiry === expiry).sort((a,b) => a.strike_price - b.strike_price || a.instrument_type.localeCompare(b.instrument_type));
  $: context = `${underlying}:${expiry}:${selectedKey}`;
  $: if (context !== identity) { identity = context; data = null; error = ''; reload(); }
  $: stale = !!data && (clock - new Date(data.receivedAt).getTime() > data.config.maxAgeSeconds * 1000 || !!error);
  $: available = data ? [data.oi.call, data.iv.call, data.vix.change, data.dow.change, data.technical.vwap, data.technical.ema, data.technical.supertrend, data.technical.sar].filter(v => v != null).length : 0;
  async function reload() {
    const gen = ++revision; controller?.abort();
    if (!underlying || !expiry || !selectedKey) { loading = false; return; }
    controller = new AbortController(); loading = true; lastFetch = Date.now();
    try {
      const res = await fetch(`/api/algo?underlying=${encodeURIComponent(underlying)}&expiry=${encodeURIComponent(expiry)}&option=${encodeURIComponent(selectedKey)}`, { signal: AbortSignal.any([controller.signal, AbortSignal.timeout(42000)]) });
      const result = await res.json(); if (!res.ok) throw new Error(result.error || 'Unable to load algorithm data');
      if (gen === revision) { data = result; error = ''; }
    } catch(e) { if (gen === revision && e.name !== 'AbortError') error = e.message; }
    finally { if (gen === revision) loading = false; }
  }
  onMount(() => {
    const timer = setInterval(() => { clock = Date.now(); if (!loading && clock - lastFetch >= (data?.config.refreshSeconds || 15) * 1000) reload(); }, 1000);
    return () => { clearInterval(timer); ++revision; controller?.abort(); };
  });
</script>

<section class="algo" aria-label="Algorithm dashboard">
  <div class="algo-intro">
    <div><span class="algo-kicker"><Activity size={13}/> STRATEGY OBSERVATORY</span><h2>See the setup. Find your conviction.</h2><p>Your market context, volatility and technicals in one place.</p></div>
    <button class="algo-refresh" onclick={reload} disabled={loading || !selectedKey}><RefreshCw size={14} class={loading ? 'spinning' : ''}/>{loading ? 'Updating…' : 'Refresh'}</button>
  </div>

  <div class="algo-context panel">
    <label>UNDERLYING<select value={underlying} onchange={e => chooseUnderlying(e.currentTarget.value, e.currentTarget.selectedOptions[0].text)}><option value="NSE_INDEX|Nifty 50">NIFTY 50</option><option value="NSE_INDEX|Nifty Bank">BANK NIFTY</option><option value="BSE_INDEX|SENSEX">SENSEX</option>{#if !['NSE_INDEX|Nifty 50','NSE_INDEX|Nifty Bank','BSE_INDEX|SENSEX'].includes(underlying)}<option value={underlying}>{underlyingName}</option>{/if}</select></label>
    <label>EXPIRY<select value={expiry} onchange={e => changeExpiry(e.currentTarget.value)} disabled={!expiries.length}>{#each expiries as date}<option value={date}>{date}</option>{/each}</select></label>
    <label class="contract-select">OPTION TO OBSERVE<select value={selectedKey} onchange={e => selectLeg(e.currentTarget.value)} disabled={!choices.length}>{#each choices as c}<option value={c.instrument_key}>{fmt(c.strike_price,0)} {c.instrument_type} · {c.trading_symbol}</option>{/each}</select></label>
    <span class="atm-chip">ATM <strong>{fmt(data?.atm,0)}</strong></span>
  </div>

  <div class="signal-panel">
    <div class="signal-main"><span class="signal-icon"><CirclePause size={27} strokeWidth={1.4}/></span><div><span class="algo-kicker">FINAL CALL · DISPLAY ONLY</span><div class="signal-title">WAIT <span>Entry rules not configured</span></div><p>This view displays market readings only. The final call stays at WAIT until you provide entry rules; the dashboard does not place a trade.</p></div></div>
    <div class="signal-coverage"><strong>{available}<span>/ 8</span></strong><span>readings available</span><small>DATA COVERAGE · NOT A SCORE</small><small>{data?.mode === 'demo' ? 'SYNTHETIC DEMO' : 'UPSTOX MARKET DATA'}</small></div>
  </div>

  {#if error}<div class="algo-alert" role="alert">{error} {data ? 'Previous snapshot shown below; not current.' : ''}</div>{/if}
  {#if stale}<div class="algo-alert">Snapshot is stale. Refresh before using these values.</div>{/if}
  {#if !data}<div class="panel algo-empty"><Activity size={28}/><h3>{loading ? 'Gathering the market picture…' : 'Select an option to begin'}</h3><p>{loading ? 'Reading the option chain, global context and completed candles.' : 'Choose an underlying, expiry and option. Custom stocks can be selected on the trading desk.'}</p></div>{:else}
    <div class="algo-meta"><span><span class="meta-dot"></span>{data.mode === 'demo' ? 'Synthetic snapshot' : 'Read-only snapshot'} · received {when(data.receivedAt)} IST</span><span>{data.marketStatus.replaceAll('_',' ')} · refresh {data.config.refreshSeconds}s</span></div>
    {#if data.chainIssue}<div class="algo-alert">{data.chainIssue}</div>{/if}
    <div class="algo-grid">
      {#each [{ title: 'Open interest', tag: 'POSITIONING', value: data.oi, wings: data.config.oiWings, iv: false }, { title: 'Implied volatility', tag: 'PREMIUM CONTEXT', value: data.iv, wings: data.config.ivWings, iv: true }] as item}
        <article class="panel algo-card">
          <div class="card-top"><span class="card-icon"><Layers size={18}/></span><span class="algo-kicker">{item.tag}</span><span class="data-tag">ATM ± {item.wings}</span></div>
          <h3>{item.title}</h3><p class="card-sub">{item.iv ? 'Average IV' : 'Total OI'} · CE vs PE · ATM included</p>
          <div class="compare-values"><div><span><i class="ce-dot"></i>CALLS · CE</span><strong title={fmt(item.value.call)}>{item.iv ? fmt(item.value.call) : compact(item.value.call)}<small>{item.iv ? '%' : ''}</small></strong></div><div><span><i class="pe-dot"></i>PUTS · PE</span><strong title={fmt(item.value.put)}>{item.iv ? fmt(item.value.put) : compact(item.value.put)}<small>{item.iv ? '%' : ''}</small></strong></div></div>
          <div class="comparison-track" aria-hidden="true"><span style:width={`${item.value.call + item.value.put > 0 ? item.value.call / (item.value.call + item.value.put) * 100 : 50}%`}></span></div>
          <div class="comparison-result"><strong>{item.value.issue ? 'Incomplete data' : item.value.leader === 'Equal' ? 'CE and PE are equal' : `${item.value.leader} is greater`}</strong>{#if item.iv && item.value.difference != null}<span class:threshold-hit={item.value.difference > data.config.ivThreshold}>{fmt(item.value.difference)} pp gap {item.value.difference > data.config.ivThreshold ? '>' : '≤'} {data.config.ivThreshold} pp</span>{:else if item.value.difference != null}<span>Difference {compact(item.value.difference)}</span>{/if}</div>
          <p class="card-foot">{item.value.issue || `${item.value.count} strikes · ${fmt(item.value.low,0)} – ${fmt(item.value.high,0)} · ${expiry}`}</p>
        </article>
      {/each}
      {#each [{ title: 'India VIX', label: 'VOLATILITY', trend: data.vix, hint: 'Inverse-market context · direction only' }, { title: 'US 30 · Dow futures', label: 'GLOBAL CONTEXT', trend: data.dow, hint: 'Watching for a move down · direction only' }] as item}
        <article class="panel algo-card trend-card">
          <div class="card-top"><span class="card-icon"><Globe2 size={18}/></span><span class="algo-kicker">{item.label}</span><span class="data-tag">{data.config.lookbackMinutes}m lookback</span></div>
          <h3>{item.title}</h3><p class="card-sub">{item.hint}</p>
          <div class="trend-value"><strong>{fmt(item.trend.current)}</strong><span class="trend-direction">{#if item.trend.issue || stale}Unavailable{:else if item.trend.direction === 'Down'}<ArrowDownRight size={19}/> Down{:else if item.trend.direction === 'Up'}<ArrowUpRight size={19}/> Up{:else}— Flat{/if}</span></div>
          <div class="trend-baseline"><span>{data.config.lookbackMinutes}m ago <strong>{fmt(item.trend.previous)}</strong></span><span>Change <strong>{item.trend.change > 0 ? '+' : ''}{fmt(item.trend.change)} <small>({fmt(item.trend.percent)}%)</small></strong></span></div>
          <p class="card-foot">{item.trend.issue || `Quote ${when(item.trend.at)} · comparison candle ${when(item.trend.previousAt)} IST`}</p>
        </article>
      {/each}
    </div>

    <section class="panel technical-panel">
      <div class="technical-heading"><div><span class="algo-kicker"><BarChart3 size={14}/> PRICE & TREND</span><h3>Technical perspective</h3><p>{data.config.target === 'underlying' ? underlyingName : currentContract?.trading_symbol} · completed 1-minute candles · session only</p></div><span class="data-tag">{data.config.target === 'underlying' ? 'UNDERLYING' : 'SELECTED OPTION'}</span></div>
      {#if data.technicalIssue}<div class="technical-note">{data.technicalIssue}</div>{/if}
      <div class="technical-grid">
        {#each [{title:'VWAP', value:data.technical.vwap, setting:data.technical.vwapSource || 'Session · typical price × volume', unavailable:data.technical.vwapIssue || 'No traded volume supplied'}, {title:`EMA ${data.config.emaPeriod}`, value:data.technical.ema, setting:`${data.config.emaPeriod} periods · SMA seed`, unavailable:`Needs ${data.config.emaPeriod} candles`}, {title:'Supertrend', value:data.technical.supertrend, setting:`ATR ${data.config.atrPeriod} · multiplier ${data.config.stMultiplier}`, unavailable:`Needs ${data.config.atrPeriod} candles`}, {title:'Parabolic SAR', value:data.technical.sar, setting:`Step ${data.config.sarStep} · max ${data.config.sarMax}`, unavailable:'Needs two completed candles'}] as indicator}
          <div class="technical-item"><span>{indicator.title}</span><strong>{fmt(indicator.value)}</strong><small>{indicator.value == null ? indicator.unavailable : data.technical.close > indicator.value ? 'Close above indicator' : data.technical.close < indicator.value ? 'Close below indicator' : 'Close at indicator'}</small><p>{indicator.setting}</p></div>
        {/each}
      </div>
      <div class="technical-footer"><span>Last completed close <strong>{fmt(data.technical.close || null)}</strong> · {when(data.technical.at)} IST</span><span>{data.technical.count} candles · no buy / sell rules applied</span></div>
    </section>
    <div class="algo-bottom"><span><ShieldCheck size={14}/> Observation only. Your paper account is unchanged.</span><span><SlidersHorizontal size={13}/> Parameters in .env · restart to apply</span></div>
  {/if}
</section>

<style>
